UPDATE workflows SET graph=$g${"nodes":[{"id":"start","type":"custom","data":{"variables":[{"variable":"user_id","label":"学生ID","description":"","type":"number","required":false,"hide":false,"max_length":null,"options":[]},{"variable":"student_name","label":"学生姓名","description":"","type":"text-input","required":false,"hide":false,"max_length":48,"options":[]},{"variable":"history_hint","label":"上文摘要","description":"","type":"paragraph","required":false,"hide":false,"max_length":null,"options":[]}],"type":"start","title":"用户输入","desc":"","selected":false,"default_value":[{"key":"user_id","type":"number","value":1},{"key":"student_name","type":"string","value":"张三"},{"key":"history_hint","type":"string","value":""}]},"position":{"x":40,"y":420},"positionAbsolute":{"x":40,"y":420},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"prepare","type":"custom","data":{"type":"template-transform","title":"拼接上下文","desc":"","variables":[{"variable":"history_hint","value_selector":["start","history_hint"]},{"variable":"query","value_selector":["sys","query"]}],"template":"{% if history_hint %}[上文] {{ history_hint }}\n[当前问题] {{ query }}{% else %}{{ query }}{% endif %}","selected":false},"position":{"x":280,"y":420},"positionAbsolute":{"x":280,"y":420},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"classifier","type":"custom","data":{"type":"question-classifier","title":"意图分类","desc":"","query_variable_selector":["prepare","output"],"model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.0,"max_tokens":800,"enable_thinking":false}},"classes":[{"id":"c_leave_apply","name":"请假申请：明确说了请假时间（哪天、几号、明天）和事由，要提交一张请假单，例如「我明天要请假一天，家里有事」「12月20号到22号要请假」"},{"id":"c_leave_query","name":"请假查询与催办：查自己交过的请假单、问审批到哪一步、催老师批、或者要求「帮我审批通过」（学生没有审批权，这类也归到这里），例如「我的请假批了吗」"},{"id":"c_emotion","name":"情绪倾诉：表达压力大、焦虑、失眠、难过、孤独，或说出「活不下去」「不想活」这类极端情绪"},{"id":"c_feedback","name":"售后反馈：投诉、对课程或住宿服务不满意、要求退费或换项目，例如「宿舍热水器坏了没人修」"},{"id":"c_score","name":"成绩查询：查考试成绩、某门课考了多少分，例如「我雅思听力多少分」"},{"id":"c_policy","name":"升学政策咨询（已指明国家或项目）：问某个国家或某个项目的政策、费用、院校、申请材料、签证，问题里出现了新加坡、德国、马来西亚、中国港澳、英美澳、双元制、本硕连读等具体国家或项目名，例如「德国留学一年多少钱」"},{"id":"c_policy_geo","name":"泛问留学但没指明国家：问留学费用、申请条件、哪个国家好、怎么选等，但问题里完全没有出现任何国家、地区或项目名，例如「留学费用大概多少钱」"},{"id":"c_other","name":"其他与敏感请求：要 API Key、密码、数据库连接串、内部系统权限这类不该给的东西；或者与留学生服务完全无关的问题（天气、写代码、闲聊）；或者系统明显办不到的事"}],"instruction":"","instructions":"","vision":{"enabled":false},"selected":false},"position":{"x":520,"y":200},"positionAbsolute":{"x":520,"y":200},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"leave_apply_http","type":"custom","data":{"type":"http-request","title":"提交请假","desc":"","method":"post","url":"http://host.docker.internal:8000/api/agent/leave-apply","authorization":{"type":"no-auth","config":null},"headers":"Content-Type:application/json\nX-Internal-Token:yj-internal-demo-2026","params":"","body":{"type":"json","data":[{"key":"","type":"text","value":"{\"student_id\":\"{{#start.user_id#}}\",\"reason\":\"{{#sys.query#}}\",\"service_type\":\"请假\"}"}]},"timeout":{"connect":10,"read":30,"write":10},"retry_config":{"retry_enabled":true,"max_retries":2,"retry_interval":500},"ssl_verify":true,"variables":[],"selected":false,"error_strategy":"default-value","default_value":[{"key":"body","type":"string","value":"{\"code\": -1, \"msg\": \"请假没有提交成功：可能是没说清时间或事由，请让对方补充哪天请假、请多久、什么原因。\"}"},{"key":"status_code","type":"number","value":400}]},"position":{"x":860,"y":40},"positionAbsolute":{"x":860,"y":40},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"leave_apply_llm","type":"custom","data":{"type":"llm","title":"请假回执","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的留学生智能管家，负责在读留学生的请假、情绪关怀、售后反馈、成绩查询和升学咨询。\n学生刚提交了请假申请，你要把申请结果清楚地告诉他。\n【铁律】\n1. 业务数据只能来自「工具返回」里的 data 字段，不许自己编造姓名、时间、分数、单号、名额。\n2. 工具返回 code 不为 0，或出现 detail / msg 里带\"未找到\"\"不存在\"\"已满\"\"非法\"\"没有权限\"等字眼时，如实转述原因，并给出一个下一步建议；不要把失败说成成功。\n3. 用中文口语回答，不要输出 JSON、不要暴露接口路径、不要提\"工具\"\"节点\"\"API\"这些词。\n4. 回答控制在 4 句话以内，需要罗列信息时用简短列表。\n5. 学生端输入若以上文形式给出（[上文] … [当前问题] …），只回答\"当前问题\"，绝不要复述[上文]里的内容。\n6. 必须说出审批人是谁：取 data.teacher.name（或 record.approver_name）的班主任姓名，\n   说成\"等你班主任李老师审批\"这种自然说法，不许只说\"等待审批\"。\n7. 如果返回里 detail 说\"没有审批权限\"或\"没有识别到请假时间\"，就照实说明，并告诉他下一步怎么做。\n","id":"82718e25-3431-4dbb-aa30-1065691aaafd"},{"role":"user","text":"学生说：{{#sys.query#}}\n\n工具返回：{{#leave_apply_http.body#}}\n\n请告诉他：申请单号、请假起止时间、天数、当前状态，以及由哪位班主任审批。","id":"0268d941-ff2a-4370-896b-e6db8d90d559"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":null,"reasoning_format":"separated","selected":false},"position":{"x":1180,"y":40},"positionAbsolute":{"x":1180,"y":40},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"leave_apply_ans","type":"custom","data":{"type":"answer","title":"请假回复","desc":"","answer":"{{#leave_apply_llm.text#}}","variables":[],"selected":false},"position":{"x":1500,"y":40},"positionAbsolute":{"x":1500,"y":40},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"leave_query_http","type":"custom","data":{"type":"http-request","title":"查询请假记录","desc":"","method":"get","url":"http://host.docker.internal:8000/api/agent/leave-list?student_id={{#start.user_id#}}","authorization":{"type":"no-auth","config":null},"headers":"Content-Type:application/json\nX-Internal-Token:yj-internal-demo-2026","params":"","body":{"type":"none","data":[]},"timeout":{"connect":10,"read":30,"write":10},"retry_config":{"retry_enabled":true,"max_retries":2,"retry_interval":500},"ssl_verify":true,"variables":[],"selected":false},"position":{"x":860,"y":260},"positionAbsolute":{"x":860,"y":260},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"leave_query_llm","type":"custom","data":{"type":"llm","title":"请假记录播报","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的留学生智能管家，负责在读留学生的请假、情绪关怀、售后反馈、成绩查询和升学咨询。\n学生要查自己的请假记录。\n【铁律】\n1. 业务数据只能来自「工具返回」里的 data 字段，不许自己编造姓名、时间、分数、单号、名额。\n2. 工具返回 code 不为 0，或出现 detail / msg 里带\"未找到\"\"不存在\"\"已满\"\"非法\"\"没有权限\"等字眼时，如实转述原因，并给出一个下一步建议；不要把失败说成成功。\n3. 用中文口语回答，不要输出 JSON、不要暴露接口路径、不要提\"工具\"\"节点\"\"API\"这些词。\n4. 回答控制在 4 句话以内，需要罗列信息时用简短列表。\n5. 学生端输入若以上文形式给出（[上文] … [当前问题] …），只回答\"当前问题\"，绝不要复述[上文]里的内容。\n6. 每条记录都必须说清审批人是谁：优先照抄 status_text，例如「已通过（李老师审批）」「待李老师审批」，\n   不许只写\"已通过\"却不说是哪位班主任批的。数据在 records[].status_text / records[].approver_name。\n7. approve_comment 有内容时，把审批意见顺带转述一句。\n8. 只要学生的话是在要求审批、催批、让你「直接通过」「帮我批」，第一句就必须先说明：\n   学生身份没有审批权限，请假只能由班主任在系统里处理；然后再把最新状态和班主任姓名告诉他。\n   不管这些单子当前是什么状态，都不许省略这句说明，更不许说「已帮你审批通过」。\n","id":"5b41f173-dc41-4f12-bf97-269d89970fd0"},{"role":"user","text":"学生说：{{#sys.query#}}\n\n工具返回：{{#leave_query_http.body#}}\n\n请按时间从新到旧列出他的请假记录（起止时间、事由、状态、审批人），没有记录就直说没有。","id":"a33b1109-bffc-4a8f-9869-38e1d1e1b924"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":null,"reasoning_format":"separated","selected":false},"position":{"x":1180,"y":260},"positionAbsolute":{"x":1180,"y":260},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"leave_query_ans","type":"custom","data":{"type":"answer","title":"请假查询回复","desc":"","answer":"{{#leave_query_llm.text#}}","variables":[],"selected":false},"position":{"x":1500,"y":260},"positionAbsolute":{"x":1500,"y":260},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"emotion_http","type":"custom","data":{"type":"http-request","title":"情绪评估与预警","desc":"","method":"post","url":"http://host.docker.internal:8000/api/agent/emotion-evaluate","authorization":{"type":"no-auth","config":null},"headers":"Content-Type:application/json\nX-Internal-Token:yj-internal-demo-2026","params":"","body":{"type":"json","data":[{"key":"","type":"text","value":"{\"student_id\":\"{{#start.user_id#}}\",\"text\":\"{{#sys.query#}}\"}"}]},"timeout":{"connect":10,"read":30,"write":10},"retry_config":{"retry_enabled":true,"max_retries":2,"retry_interval":500},"ssl_verify":true,"variables":[],"selected":false},"position":{"x":860,"y":480},"positionAbsolute":{"x":860,"y":480},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"emotion_llm","type":"custom","data":{"type":"llm","title":"心理关怀话术","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.8,"max_tokens":900,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的留学生智能管家，此刻在陪一个正在难受的学生说话。你要像一个靠得住的班主任那样开口，不要像客服，也不要说教。\n\n【第一步：先分清他在哪一类，再决定说什么】\n1. 当下危险：说想跳楼、人已经在天台或窗边、手上有刀、已经在做危险的事。\n   → 先确认他此刻在哪、身边有没有人；让他离开危险的位置（从窗边下来、把手里的东西放下）；再告诉他班主任马上联系他。\n2. 自杀念头：说不想活、想死、活着没意思，但没说已经在做。\n   → 别急着讲道理，先接住「撑不下去」这件事；帮他把「一辈子」缩成「这一小时」，找一个具体的人或事陪他撑过去。\n3. 自伤：割腕、划手、伤害自己。\n   → 先问伤口情况、有没有流血，先把伤口处理了，再谈情绪。\n4. 长期消耗：失眠、焦虑、厌学、天天撑着。\n   → 问清楚持续多久、最影响睡觉还是上课；给一个今晚就能做的小动作，不要一次给一堆。\n5. 人际与家庭：被孤立、被排挤、失恋、跟父母吵翻。\n   → 先站在他这边，不说「你也有问题」；再给他一句明天能对谁说的话。\n\n实在分不清，就先问一句具体的（例如「是刚发生了什么事，还是这种感觉已经很久了？」），不要猜。\n\n【第二步：怎么说】\n1. 第一句必须回应他这句话里的具体内容，可以引用他自己的词（「你说想跳楼」），不许用「听到你这么说」「我非常理解你」这类万能开头。\n2. 每一类给的动作必须不一样：危机给「离开危险位置、找人陪着」；绝望给「先撑过这一小时」；失眠给「今晚怎么睡」；人际给「下一步跟谁说、说什么」。不要什么都回「深呼吸、打热线」。\n3. 说 2~4 句，句子短，像面对面讲话；不要编号罗列，不要一次给很多建议，只给一个最该做的。\n4. 只有当工具返回里 alerted 为 true 时，才用一句自然的话说明「我已经叫班主任联系你」，并说清大概什么时候；不要每轮重复同一句，也不要说成系统通知。\n5. 不许做医学诊断（不说「你抑郁了」），不许承诺保密，不许评判他对错，不许说「我完全理解你的感受」这类空话。\n6. 不许把分类说出来：不要出现「这属于长期消耗」「这是当下危险」「你属于自杀念头」这类贴标签的话，直接对着他的事说人话。\n7. 业务数据只能来自「工具返回」里的 data 字段，不许编造姓名、班级、时间、分数、单号、名额。\n8. 用中文口语回答，不要输出 JSON、不要暴露接口路径、不要提「工具」「节点」「API」。\n9. 学生端输入若以上文形式给出（[上文] … [当前问题] …），只回答「当前问题」，不要复述[上文]里的内容。"},{"role":"user","text":"学生说：{{#sys.query#}}\n\n工具返回：{{#emotion_http.body#}}\n\n先判断他属于哪一类（当下危险 / 自杀念头 / 自伤 / 长期消耗 / 人际家庭），再按对应的方式回应：第一句接住他具体说的那句话，然后只给一个最该做的动作。"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":null,"reasoning_format":"separated","selected":false},"position":{"x":1180,"y":480},"positionAbsolute":{"x":1180,"y":480},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"emotion_ans","type":"custom","data":{"type":"answer","title":"关怀回复","desc":"","answer":"{{#emotion_llm.text#}}","variables":[],"selected":false},"position":{"x":1500,"y":480},"positionAbsolute":{"x":1500,"y":480},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"feedback_http","type":"custom","data":{"type":"http-request","title":"创建反馈工单","desc":"","method":"post","url":"http://host.docker.internal:8000/api/agent/feedback-create","authorization":{"type":"no-auth","config":null},"headers":"Content-Type:application/json\nX-Internal-Token:yj-internal-demo-2026","params":"","body":{"type":"json","data":[{"key":"","type":"text","value":"{\"student_id\":\"{{#start.user_id#}}\",\"content\":\"{{#sys.query#}}\"}"}]},"timeout":{"connect":10,"read":30,"write":10},"retry_config":{"retry_enabled":true,"max_retries":2,"retry_interval":500},"ssl_verify":true,"variables":[],"selected":false,"error_strategy":"default-value","default_value":[{"key":"body","type":"string","value":"{\"code\": -1, \"msg\": \"这条反馈没有生成工单：可能不是真实的服务反馈，请如实说明原因。\"}"},{"key":"status_code","type":"number","value":400}]},"position":{"x":860,"y":700},"positionAbsolute":{"x":860,"y":700},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"feedback_llm","type":"custom","data":{"type":"llm","title":"工单回执","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的留学生智能管家，负责在读留学生的请假、情绪关怀、售后反馈、成绩查询和升学咨询。\n学生提交了售后反馈，你要给他工单回执。\n【铁律】\n1. 业务数据只能来自「工具返回」里的 data 字段，不许自己编造姓名、时间、分数、单号、名额。\n2. 工具返回 code 不为 0，或出现 detail / msg 里带\"未找到\"\"不存在\"\"已满\"\"非法\"\"没有权限\"等字眼时，如实转述原因，并给出一个下一步建议；不要把失败说成成功。\n3. 用中文口语回答，不要输出 JSON、不要暴露接口路径、不要提\"工具\"\"节点\"\"API\"这些词。\n4. 回答控制在 4 句话以内，需要罗列信息时用简短列表。\n5. 学生端输入若以上文形式给出（[上文] … [当前问题] …），只回答\"当前问题\"，绝不要复述[上文]里的内容。","id":"7970a3d9-ba76-48df-bea8-eb2ffa45fe0b"},{"role":"user","text":"学生说：{{#sys.query#}}\n\n工具返回：{{#feedback_http.body#}}\n\n请告诉他工单编号、当前处理状态，以及大概多久会有老师联系他；如果没建成，就说清为什么。","id":"14fb720f-66f7-44db-9309-73ab7697b038"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":null,"reasoning_format":"separated","selected":false},"position":{"x":1180,"y":700},"positionAbsolute":{"x":1180,"y":700},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"feedback_ans","type":"custom","data":{"type":"answer","title":"反馈回复","desc":"","answer":"{{#feedback_llm.text#}}","variables":[],"selected":false},"position":{"x":1500,"y":700},"positionAbsolute":{"x":1500,"y":700},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"score_http","type":"custom","data":{"type":"http-request","title":"查询成绩","desc":"","method":"get","url":"http://host.docker.internal:8000/api/agent/score-list?student_id={{#start.user_id#}}&course={{#sys.query#}}","authorization":{"type":"no-auth","config":null},"headers":"Content-Type:application/json\nX-Internal-Token:yj-internal-demo-2026","params":"","body":{"type":"none","data":[]},"timeout":{"connect":10,"read":30,"write":10},"retry_config":{"retry_enabled":true,"max_retries":2,"retry_interval":500},"ssl_verify":true,"variables":[],"selected":false},"position":{"x":860,"y":920},"positionAbsolute":{"x":860,"y":920},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"score_llm","type":"custom","data":{"type":"llm","title":"成绩播报","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的留学生智能管家，负责在读留学生的请假、情绪关怀、售后反馈、成绩查询和升学咨询。\n学生要查成绩。\n【铁律】\n1. 业务数据只能来自「工具返回」里的 data 字段，不许自己编造姓名、时间、分数、单号、名额。\n2. 工具返回 code 不为 0，或出现 detail / msg 里带\"未找到\"\"不存在\"\"已满\"\"非法\"\"没有权限\"等字眼时，如实转述原因，并给出一个下一步建议；不要把失败说成成功。\n3. 用中文口语回答，不要输出 JSON、不要暴露接口路径、不要提\"工具\"\"节点\"\"API\"这些词。\n4. 回答控制在 4 句话以内，需要罗列信息时用简短列表。\n5. 学生端输入若以上文形式给出（[上文] … [当前问题] …），只回答\"当前问题\"，绝不要复述[上文]里的内容。\n6. 如果问的是某一门课（例如雅思听力），只答那一门；返回 data 为空就直说「系统里还没有这门课的成绩」，\n   一句话说完即可，不许拿别的课程顶替，不许编分数，也不许列出\"课程名：无/分数：无\"这种空壳字段。\n","id":"9014754c-d8c2-4faa-be08-a1bd6c34a18d"},{"role":"user","text":"学生说：{{#sys.query#}}\n\n工具返回：{{#score_http.body#}}\n\n请用列表列出课程名、分数、学期，并顺带说一句平均分；只问一门课就直接报那一门。","id":"afcd4e1b-2964-43fa-9138-c262f44b5166"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":null,"reasoning_format":"separated","selected":false},"position":{"x":1180,"y":920},"positionAbsolute":{"x":1180,"y":920},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"score_ans","type":"custom","data":{"type":"answer","title":"成绩回复","desc":"","answer":"{{#score_llm.text#}}","variables":[],"selected":false},"position":{"x":1500,"y":920},"positionAbsolute":{"x":1500,"y":920},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"geo_ask_llm","type":"custom","data":{"type":"llm","title":"反问国家","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的留学顾问。学生问了一个留学相关问题，但没有说明想去哪个国家或地区。\n你的任务：先用一句话确认他想了解哪个国家/地区，再列出你们主要做的方向让他选。\n可选方向：新加坡、德国、马来西亚、中国港澳、英国/澳洲、中外合作办学（2+2、本硕连读）。\n如果[上文]里已经提到过某个国家或项目，就直接按那个国家回答，不要再反问。\n不要直接报某一国的费用或条件，不要编造数字。整段控制在 4 句话以内。","id":"87b5cb5d-7a17-4b05-85c2-0c444b9a3782"},{"role":"user","text":"学生对你说：{{#sys.query#}}\n\n上文：{{#start.history_hint#}}\n\n请反问他具体想了解哪个国家或地区。","id":"044b9ee2-92d7-4548-a7dc-1d251ace4758"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":null,"reasoning_format":"separated","selected":false},"position":{"x":1180,"y":1140},"positionAbsolute":{"x":1180,"y":1140},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"geo_ask_ans","type":"custom","data":{"type":"answer","title":"反问回复","desc":"","answer":"{{#geo_ask_llm.text#}}","variables":[],"selected":false},"position":{"x":1500,"y":1140},"positionAbsolute":{"x":1500,"y":1140},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"kb_retrieval","type":"custom","data":{"type":"knowledge-retrieval","title":"知识检索","desc":"","query_variable_selector":["sys","query"],"dataset_ids":["ef37795b-f4f8-47da-933f-739942b47692"],"retrieval_mode":"multiple","multiple_retrieval_config":{"top_k":10,"score_threshold":0.3,"score_threshold_enabled":true,"reranking_mode":"reranking_model","reranking_enable":false,"reranking_model":{"provider":"langgenius/tongyi/tongyi","model":"qwen3-vl-rerank"}},"selected":false},"position":{"x":860,"y":1360},"positionAbsolute":{"x":860,"y":1360},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"kb_llm","type":"custom","data":{"type":"llm","title":"知识库问答","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的留学政策顾问，回答学生关于政策、费用、院校、申请材料、签证的问题。\n【判断国家】只有当问题（含[上文]）里完全没出现国家、地区或项目名（新加坡、德国、马来西亚、中国港澳、英美澳、双元制、本硕连读等）时，才先反问「你想了解哪个国家/地区」；只要出现了，就直接回答那一国，绝对不要反问。\n【承接上文】如果[上文]里提到过某个项目（例如「0.5/1+2 本硕连读」），而当前问题只是「学费多少」「怎么报名」「要什么条件」，就理解为在问那个项目，按那个项目回答。\n【报名类问题】问到「怎么报名 / 报名流程 / 要准备什么材料」时，必须按资料给出完整五步：提交报名材料 → 材料核查通过 → 参加入学笔试及面试 → 入学条件审核通过后缴纳第一年费用 → 发放入学通知/Offer；可以补充笔试(40%)+面试(60%)的构成。不能只回一句「找顾问老师」。\n只依据下面检索到的资料回答；涉及费用、分数、年限、时间节点时照抄资料原文，不要自己换算或编造。\n资料没覆盖的，直接说「这个我不确定，建议你联系顾问老师确认」。\n打工时长、签证条款、移民条件这类法规细节，资料里没明确写就不要自己补数字，改为「具体以官方最新政策为准，建议顾问老师帮你确认」。\n学生说清了国家和问题时，第一句先直接回答，再用分条补充细节，整体控制在 6 句话以内。","id":"c81e11cc-a583-46ef-abef-b7b704376516"},{"role":"user","text":"学生问：{{#sys.query#}}\n\n上文：{{#start.history_hint#}}\n\n参考资料：{{#context#}}","id":"c6c7d97a-0f11-4a01-a1d0-3edc9dbd2335"}],"context":{"enabled":true,"variable_selector":["kb_retrieval","result"]},"vision":{"enabled":false},"memory":{"role_prefix":{"user":"用户","assistant":"助手"},"window":{"enabled":true,"size":4},"query_prompt_template":null},"reasoning_format":"separated","selected":false},"position":{"x":1180,"y":1360},"positionAbsolute":{"x":1180,"y":1360},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"kb_ans","type":"custom","data":{"type":"answer","title":"咨询回复","desc":"","answer":"{{#kb_llm.text#}}","variables":[],"selected":false},"position":{"x":1500,"y":1360},"positionAbsolute":{"x":1500,"y":1360},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"other_llm","type":"custom","data":{"type":"llm","title":"能力边界说明","desc":"","model":{"provider":"langgenius/tongyi/tongyi","name":"qwen3.8-flash","mode":"chat","completion_params":{"temperature":0.3,"max_tokens":2000,"enable_thinking":false}},"prompt_template":[{"role":"system","text":"你是「粤教服务」的留学生智能管家，负责在读留学生的请假、情绪关怀、售后反馈、成绩查询和升学咨询。\n学生提了一个你不能办的请求。你要做的是：说清边界 + 给出正确的办理方式，不要道歉过度、不要编造。\n- 要密钥、密码、数据库连接串、后台权限：明确拒绝，说明这些信息不对学生开放，也不会通过对话给出。\n- 与技术实现、代码、其他同学数据相关：说明你只负责本人的留学事务。\n- 与留学完全无关（天气、闲聊）：一句话说清你的职责范围，并把话题拉回留学服务。\n- 办不到的事：说清需要找谁（班主任 / 顾问老师 / 行政）。\n【铁律】\n1. 业务数据只能来自「工具返回」里的 data 字段，不许自己编造姓名、时间、分数、单号、名额。\n2. 工具返回 code 不为 0，或出现 detail / msg 里带\"未找到\"\"不存在\"\"已满\"\"非法\"\"没有权限\"等字眼时，如实转述原因，并给出一个下一步建议；不要把失败说成成功。\n3. 用中文口语回答，不要输出 JSON、不要暴露接口路径、不要提\"工具\"\"节点\"\"API\"这些词。\n4. 回答控制在 4 句话以内，需要罗列信息时用简短列表。\n5. 学生端输入若以上文形式给出（[上文] … [当前问题] …），只回答\"当前问题\"，绝不要复述[上文]里的内容。","id":"833fca11-cb11-4a0f-a9b5-35fd209a21ec"},{"role":"user","text":"学生说：{{#sys.query#}}\n\n","id":"af02e115-b6a5-4f64-bba0-5fdcd3501c1e"}],"context":{"enabled":false,"variable_selector":[]},"vision":{"enabled":false},"memory":null,"reasoning_format":"separated","selected":false},"position":{"x":1180,"y":1580},"positionAbsolute":{"x":1180,"y":1580},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false},{"id":"other_ans","type":"custom","data":{"type":"answer","title":"说明回复","desc":"","answer":"{{#other_llm.text#}}","variables":[],"selected":false},"position":{"x":1500,"y":1580},"positionAbsolute":{"x":1500,"y":1580},"targetPosition":"left","sourcePosition":"right","width":242,"height":100,"selected":false}],"edges":[{"id":"start-source-prepare-target","type":"custom","source":"start","sourceHandle":"source","target":"prepare","targetHandle":"target","data":{"sourceType":"start","targetType":"template-transform","isInIteration":false,"isInLoop":false},"zIndex":0},{"id":"prepare-source-classifier-target","type":"custom","source":"prepare","sourceHandle":"source","target":"classifier","targetHandle":"target","data":{"sourceType":"template-transform","targetType":"question-classifier","isInIteration":false,"isInLoop":false},"zIndex":0},{"id":"classifier-c_leave_apply-leave_apply_http-target","type":"custom","source":"classifier","sourceHandle":"c_leave_apply","target":"leave_apply_http","targetHandle":"target","data":{"sourceType":"question-classifier","targetType":"http-request","isInIteration":false,"isInLoop":false},"zIndex":0},{"id":"leave_apply_http-source-leave_apply_llm-targ